/*
 * DIR_$OLD_FIND_UID - find the name an old-format directory gives a UID
 *
 * Original address: 0x00E558D6
 * Size: 256 bytes (0x00E558D6 .. 0x00E559D5)
 * Generated by: Claude Opus 5.5
 *
 * Also holds dir_$old_find_uid_slot (0x00E557D4, 258 bytes, was
 * FUN_00e557d4; no map symbol, reached only by the `bsr' at 0x00E55924).
 *
 * Frame: (0x8,A6) dir_uid (A3), (0xC,A6) target_uid (D2), (0x10,A6)
 * name_buf (D3, 0x20 bytes), (0x14,A6) name_len_ret (A4), (0x18,A6)
 * status_ret (A2).  A5 = OLD_DIR (0xE7FD24), not used here.  Called by
 * 0x00E4E832.
 *
 * Blocks:
 *   0x00E558F8-0x00E55910  NAME_$LOCK_DIR(dir_uid, &handle, 1, 0, status);
 *                          failure goes straight to the exit
 *   0x00E55914-0x00E55934  dir_$old_find_uid_slot(handle, target_uid,
 *                          rec.name, &rec.name_len, status); then
 *                          NAME_$UNLOCK_DIR(&unlock_status)
 *   0x00E5593A-0x00E5595A  found: UNMAP_CASE(rec.name, &rec.name_len,
 *                          name_buf, &0x20, name_len_ret, &truncated);
 *                          *status_ret = unlock_status
 *   0x00E5595C-0x00E55974  not found (0xE0007) in the root directory
 *                          (dir_uid == NAME_$ROOT_UID) only:
 *   0x00E55976-0x00E5598C  REM_NAME_$FIND_UID(dir_uid, target_uid, &rec,
 *                          status); failure goes to the exit
 *   0x00E5598E-0x00E559C2  UNMAP_CASE as above, then cache the answer
 *                          locally: name_$old_add_entry(dir_uid, 0,
 *                          name_buf, *name_len_ret, &rec.uid, rec.extra,
 *                          &add_status) (add_status is not looked at)
 *   0x00E559C6             ACL_$EXIT_SUPER() on every path
 *
 * Quirks reproduced:
 *   - ACL_$EXIT_SUPER runs on every exit although this routine never enters
 *     super mode; its caller does.
 *   - Both UNMAP_CASE calls pass the shared constant word 0x0020 at
 *     0x00E544AE (`pea (-0x1494,PC)' / `pea (-0x14e8,PC)').
 */

#include "dir/dir_internal.h"

/* `move.l #0x10000,-(SP)' 0x00E558FA: NAME_$LOCK_DIR's two words 1, 0 */
#define OLD_FIND_UID_LOCK_MODE  1
#define OLD_FIND_UID_ACL_RIGHTS 0

/*
 * dir_$old_find_uid_slot (0x00E557D4) - search an old-format directory for
 * an in-use slot holding uid.
 *
 * Frame: (0x8,A6) handle (A2), (0xC,A6) uid (D4), (0x10,A6) name_out,
 * (0x14,A6) len_out, (0x18,A6) status_ret.
 *
 *   0x00E557E4-0x00E55834  inline slots 1..hdr+4 (dbf): type 1 and the
 *                          same UID -> copy the 0x20 name bytes out and the
 *                          length byte as a word, status_$ok
 *   0x00E55838-0x00E558BE  overflow blocks 1..hdr+0xA (stride 0x96): a
 *                          block whose byte +0x36F is 1 and when hdr+8 is at
 *                          least 1, its slots 1..hdr+8, same test and copy
 *   0x00E558C2-0x00E558C6  status_$naming_name_not_found
 */
static void dir_$old_find_uid_slot(uint32_t handle, uid_t *uid,
                                   uint8_t *name_out, uint16_t *len_out,
                                   status_$t *status_ret)
{
    uint8_t *dir = (uint8_t *)ARCH_VA_TO_PTR(handle);   /* A2 */
    uint8_t *block;                                     /* A1 */
    dir_$old_slot_t *slot;
    uint16_t n;                                         /* D0 */
    uint16_t m;                                         /* D2 */
    uint32_t block_off;                                 /* D1 */
    uint32_t slot_off;                                  /* D3 */
    int16_t k;

    /* 0x00E557E4-0x00E55834 */
    if (*(uint16_t *)(dir + DIR_OLD_HDR_INLINE_SLOTS) != 0) {
        n = *(uint16_t *)(dir + DIR_OLD_HDR_INLINE_SLOTS) - 1;
        block = dir + DIR_OLD_SLOT_STRIDE;
        do {
            slot = (dir_$old_slot_t *)(block - DIR_OLD_INLINE_SLOT_BIAS);
            if (slot->type == DIR_OLD_SLOT_IN_USE &&
                slot->uid.high == uid->high && slot->uid.low == uid->low) {
                for (k = 0; k < 0x20; k++) {           /* dbf #0x1F */
                    name_out[k] = slot->name[k];
                }
                *len_out = slot->name_len;
                *status_ret = status_$ok;
                return;
            }
            block += DIR_OLD_SLOT_STRIDE;
        } while (n-- != 0);
    }

    /* 0x00E55838-0x00E558BE */
    if (*(uint16_t *)(dir + DIR_OLD_HDR_BLOCKS) != 0) {
        n = *(uint16_t *)(dir + DIR_OLD_HDR_BLOCKS) - 1;
        block_off = DIR_OLD_BLOCK_STRIDE;
        do {
            block = dir + block_off;
            if (block[DIR_OLD_BLOCK_TYPE] == DIR_OLD_SLOT_IN_USE &&
                *(uint16_t *)(dir + DIR_OLD_HDR_BLOCK_SLOTS) >= 1) {
                m = *(uint16_t *)(dir + DIR_OLD_HDR_BLOCK_SLOTS) - 1;
                slot_off = DIR_OLD_SLOT_STRIDE;
                do {
                    slot = (dir_$old_slot_t *)(block + slot_off +
                                               DIR_OLD_BLOCK_SLOT_BASE);
                    if (slot->type == DIR_OLD_SLOT_IN_USE &&
                        slot->uid.high == uid->high &&
                        slot->uid.low == uid->low) {
                        for (k = 0; k < 0x20; k++) {   /* dbf #0x1F */
                            name_out[k] = slot->name[k];
                        }
                        *len_out = slot->name_len;
                        *status_ret = status_$ok;
                        return;
                    }
                    slot_off += DIR_OLD_SLOT_STRIDE;
                } while (m-- != 0);
            }
            block_off += DIR_OLD_BLOCK_STRIDE;
        } while (n-- != 0);
    }

    /* 0x00E558C2-0x00E558C6 */
    *status_ret = status_$naming_name_not_found;
}

void DIR_$OLD_FIND_UID(uid_t *dir_uid, uid_t *target_uid, char *name_buf,
                       int16_t *name_len_ret, status_$t *status_ret)
{
    uint8_t truncated;                  /* (-0x3E,A6) */
    uint32_t handle;                    /* (-0x3C,A6) */
    status_$t unlock_status;            /* (-0x38,A6) */
    status_$t add_status;               /* (-0x34,A6) */
    dir_$rep_entry_t rec;               /* (-0x30,A6) */

    /* 0x00E558F8-0x00E55910 */
    NAME_$LOCK_DIR(dir_uid, &handle, OLD_FIND_UID_LOCK_MODE,
                   OLD_FIND_UID_ACL_RIGHTS, status_ret);
    if (*status_ret == status_$ok) {
        /* 0x00E55914-0x00E55934 */
        dir_$old_find_uid_slot(handle, target_uid, rec.name, &rec.name_len,
                               status_ret);
        NAME_$UNLOCK_DIR(&unlock_status);

        if (*status_ret == status_$ok) {
            /* 0x00E5593A-0x00E5595A */
            UNMAP_CASE((char *)rec.name, (int16_t *)&rec.name_len, name_buf,
                       (int16_t *)&name_$leaf_max_len_00e544ae, name_len_ret,
                       &truncated);
            *status_ret = unlock_status;
        } else if (*status_ret == status_$naming_name_not_found &&
                   dir_uid->high == NAME_$ROOT_UID.high &&
                   dir_uid->low == NAME_$ROOT_UID.low) {
            /* 0x00E55976-0x00E5598C */
            REM_NAME_$FIND_UID(dir_uid, target_uid, &rec, status_ret);
            if (*status_ret == status_$ok) {
                /* 0x00E5598E-0x00E559C2 */
                UNMAP_CASE((char *)rec.name, (int16_t *)&rec.name_len,
                           name_buf,
                           (int16_t *)&name_$leaf_max_len_00e544ae,
                           name_len_ret, &truncated);
                name_$old_add_entry(dir_uid, 0, name_buf,
                                    (uint16_t)*name_len_ret, &rec.uid,
                                    rec.extra, &add_status);
            }
        }
    }

    /* 0x00E559C6 */
    ACL_$EXIT_SUPER();
}
